import { Checkbox, Combobox, Group, TextInput, useCombobox } from '@xiaoye-react/ui';
import classes from './SelectList.module.css';

const groceries = ['🍎 苹果', '🍌 香蕉', '🥦 西兰花', '🥕 胡萝卜', '🍫 巧克力'];

export function SelectList() {
  const combobox = useCombobox();

  const [value, setValue] = useState<string[]>([]);
  const [search, setSearch] = useState('');

  const handleValueSelect = (val: string) =>
    setValue((current) =>
      current.includes(val) ? current.filter((v) => v !== val) : [...current, val]
    );

  const options = groceries
    .filter((item) => item.toLowerCase().includes(search.toLowerCase().trim()))
    .map((item) => (
      <Combobox.Option
        value={item}
        key={item}
        active={value.includes(item)}
        onMouseOver={() => combobox.resetSelectedOption()}
      >
        <Group gap="sm">
          <Checkbox
            checked={value.includes(item)}
            onChange={() => {}}
            aria-hidden
            tabIndex={-1}
            style={{ pointerEvents: 'none' }}
          />
          <span>{item}</span>
        </Group>
      </Combobox.Option>
    ));

  return (
    <Combobox store={combobox} onOptionSubmit={handleValueSelect}>
      <Combobox.EventsTarget>
        <TextInput
          placeholder="搜索杂货"
          classNames={{ input: classes.input }}
          value={search}
          onChange={(event) => {
            setSearch(event.currentTarget.value);
            combobox.updateSelectedOptionIndex();
          }}
        />
      </Combobox.EventsTarget>

      <div className={classes.list}>
        <Combobox.Options>
          {options.length > 0 ? options : <Combobox.Empty>未找到....</Combobox.Empty>}
        </Combobox.Options>
      </div>
    </Combobox>
  );
}

  background-color: var(--ui-color-body);
  padding: var(--ui-spacing-xs) 6px;
  border: 1px solid light-dark(var(--ui-color-gray-4), var(--ui-color-dark-4));
  border-top: 0;
  border-bottom-left-radius: var(--ui-radius-md);
  border-bottom-right-radius: var(--ui-radius-md);
  min-height: 190px;
}

.input {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}
